if [ "$T8" = rebooted ] && [ -s $P/itest-reboot-q2.containers.pre ] && grep -q . $P/itest-reboot-q2.events.pre && grep -q . $P/itest-reboot-q2.docker-mount.pre; then n=0; CRC=; while :; do timeout 20 ssh -n -o BatchMode=yes -o ConnectTimeout=10 egw-tcg 'docker ps -q --no-trunc --filter status=running | sort' > $P/itest-reboot-q2.containers.post 2>/dev/null; CRC=$?; [ "$CRC" = 0 ] && cmp -s $P/itest-reboot-q2.containers.pre $P/itest-reboot-q2.containers.post && break; n=$((n + 1)); [ "$n" -lt 90 ] || break; sleep 10; done; if [ "$CRC" = 0 ] && cmp -s $P/itest-reboot-q2.containers.pre $P/itest-reboot-q2.containers.post; then echo "CONTAINERS RETURNED UNAIDED: the $(wc -l < $P/itest-reboot-q2.containers.pre) container ids saved before the reboot are listed running again (read $((n + 1)) of at most 90, 10 s apart, each bounded to 20 s; these lines started nothing)"; timeout 20 ssh -n -o BatchMode=yes -o ConnectTimeout=10 egw-tcg 'ls -1 /opt/egw/deployment/data/events | sort' > $P/itest-reboot-q2.events.post 2>/dev/null; ERC=$?; timeout 20 ssh -n -o BatchMode=yes -o ConnectTimeout=10 egw-tcg 'findmnt -no SOURCE /var/lib/docker' > $P/itest-reboot-q2.docker-mount.post 2>/dev/null; MRC=$?; MISSING=$(LC_ALL=C comm -23 <(LC_ALL=C sort $P/itest-reboot-q2.events.pre) <(LC_ALL=C sort $P/itest-reboot-q2.events.post)); if [ "$ERC" != 0 ] || [ "$MRC" != 0 ]; then stop "test 8: persistence NOT shown - a judged read did NOT end with exit status 0 (the event directories' read: exit $ERC; the mount source's read: exit $MRC; 124 is a read ended by its 20 s timeout, 255 an ssh that did not connect or lost its connection, and 1 with nothing printed is findmnt's answer for no mount at that path): what such a read printed is no answer - it is kept as a diagnostic in $P/itest-reboot-q2.events.post and $P/itest-reboot-q2.docker-mount.post ('$(cat $P/itest-reboot-q2.docker-mount.post)') and judged by nothing - the containers' return stands as printed, and these lines created nothing; look at the guest (ls -la /opt/egw/deployment/data/events; findmnt /var/lib/docker; lsblk) and record the finding"; elif [ -z "$MISSING" ] && cmp -s $P/itest-reboot-q2.docker-mount.pre $P/itest-reboot-q2.docker-mount.post; then echo "PERSISTENCE SHOWN: $(wc -l < $P/itest-reboot-q2.events.pre) event directories intact; /var/lib/docker on $(cat $P/itest-reboot-q2.docker-mount.post)"; timeout 60 ssh -n -o BatchMode=yes -o ConnectTimeout=10 egw-tcg 'systemctl is-system-running; systemctl --failed --no-legend; sudo journalctl --list-boots | tail -n 3; sudo journalctl -b -1 -u docker.service --no-pager | tail -n 5; docker ps --format "{{.Names}} {{.Status}}"; df -h / /var/lib/docker'; echo "observations read, exit $? (not a judgement: the set, the directories and the mount source above are)"; T8=returned; elif [ -n "$MISSING" ]; then stop "test 8: persistence NOT shown - $(echo $MISSING | wc -w) of the $(wc -l < $P/itest-reboot-q2.events.pre) event directories saved before the reboot ($P/itest-reboot-q2.events.pre) are NOT listed after it: $(echo $MISSING) (an empty $P/itest-reboot-q2.events.post is no directory listed: the read itself ended with exit status 0) - the containers' return stands as printed, and these lines created nothing; look at the guest (ls -la /opt/egw/deployment/data/events; findmnt /var/lib/docker) and record the finding"; else stop "test 8: persistence NOT shown - /var/lib/docker is on '$(cat $P/itest-reboot-q2.docker-mount.post)' after the reboot, not on '$(cat $P/itest-reboot-q2.docker-mount.pre)' as before it (findmnt -no SOURCE, a read that ended with exit status 0; the data disk of 3.2) - the containers' return stands as printed and all $(wc -l < $P/itest-reboot-q2.events.pre) event directories are listed again; look at the guest (findmnt /var/lib/docker; lsblk) and record the finding"; fi; else diff $P/itest-reboot-q2.containers.pre $P/itest-reboot-q2.containers.post; stop "test 8: the containers did NOT return unaided within 90 reads 10 s apart - no read both ended with exit status 0 and listed the saved set (the last read ended with exit $CRC: 124 is a read ended by its 20 s timeout, 255 an ssh that did not connect or lost its connection; what it printed is kept in $P/itest-reboot-q2.containers.post and is the diff above: '<' saved before the reboot, '>' read now; no diff line with a non-zero exit is the saved set printed by a read that did not succeed, which is no answer; an empty 'now' is no container running, or nothing printed) - do NOT compose up/start/restart anything: that would be an aided return, which test 8 does not accept; look at the guest (systemctl status docker; docker ps -a) and record the finding"; fi; else stop "test 8: the reboot is not shown by the line above (T8='$T8'), or $P/itest-reboot-q2.containers.pre, $P/itest-reboot-q2.events.pre or $P/itest-reboot-q2.docker-mount.pre is missing or empty - nothing was read"; fi
